function code(file: string, language: string, text: string, provenance: StageCode['provenance'], sourceUrl: string, highlight: number[] = [1]): StageCode {
  return { file, language, text, provenance, sourceUrl, highlight };
}
const api = (file: string, language: string, text: string, sourceUrl: string, highlight?: number[]) => code(file, language, text, 'Documented API example', sourceUrl, highlight);
const pseudo = (file: string, text: string, sourceUrl: string, highlight?: number[]) => code(file, 'text', text, 'Illustrative pseudocode', sourceUrl, highlight);
const wire = (file: string, text: string, sourceUrl: string, highlight?: number[]) => code(file, 'json', text, 'Illustrative wire payload', sourceUrl, highlight);
const original = code('help.md', 'markdown', '# Welcomme\n\nFind answers in our [FAQ](./faq.md).\n', 'Workshop file', './workshop/help.md', [1, 3]);
const instructions = (file = 'AGENTS.md') => code(file, 'markdown', file === 'CLAUDE.md' ? "@AGENTS.md\n\nThe imported file contains the shared contract for this practice directory.\n" : "# Harness engineering practice task\n\nThis directory is a disposable teaching fixture, not a production project.\n\n- Read help.md and the current user task before editing.\n- The only allowed edit is one replacement of Welcomme with Welcome in help.md.\n- Preserve every other byte, including the FAQ link and trailing newline.\n- Preserve every other file. Do not add files or directories.\n- Do not edit verify.mjs, faq.md, README.md, AGENTS.md or CLAUDE.md.\n- If the starting document differs from the fixture, stop and report the mismatch.\n- Run `node verify.mjs` and report its exit code and the exact edit.\n- Do not commit, publish, access the network or change permission settings.\n\nThese instructions guide behavior; they do not install a permission boundary.\nThe learner runs an additional trusted verifier from outside this working copy.\n", 'Workshop file', `./workshop/${file}`, file === 'CLAUDE.md' ? [1] : [6, 7, 8]);
const verifier = code('verify.mjs · file-check excerpt', 'javascript', "const bytes = await readFile(join(root, name));\nif (name === 'help.md') {\nif (!bytes.equals(Buffer.from(expectedHelp))) {\nfailures.push('help.md: expected only Welcomme \u2192 Welcome; preserve all other bytes.');\n}\n} else if (name === 'verify.mjs') {\nif (!bytes.equals(await readFile(trustedScript))) {\nfailures.push('verify.mjs: differs from the trusted verifier being executed.');\n}\n} else {\nconst hash = createHash('sha256').update(bytes).digest('hex');\nif (hash !== protectedHashes[name]) failures.push(`${name}: protected file changed.`);\n}", 'Workshop file', './workshop/verify.mjs', [3, 7, 12]);
const diff = pseudo('help.md · expected diff', '- # Welcomme\n+ # Welcome\n\n  Find answers in our [FAQ](./faq.md).\n\nOnly the heading changes. The relative link is invariant.', './workshop/help.md', [1, 2, 4]);
const task = pseudo('workshop task · acceptance contract', 'Change: Welcomme → Welcome in help.md\nBoundary: preserve every other character\nInvariant: [FAQ](./faq.md) and faq.md unchanged\nIndependent evidence: node ../harness-starter/verify.mjs . exits 0\nIf the check fails: correct the file, then check again', './workshop/README.md', [1, 2, 3, 4]);

