type Item = [label: string, asset: StageAsset, detail: string, snippet: StageCode];
type Story = { title: string; nodes: Item[]; beats: [string, string][]; blocked?: number };
const item = (label: string, asset: StageAsset, detail: string, snippet: StageCode): Item => [label, asset, detail, snippet];
const target = () => item('help.md', 'editor', 'A real file in the downloadable starter kit. Inspect the typo and the relative FAQ link.', original);
const output = () => item('One-line document diff', 'diff-board', 'The expected change affects the heading only. This visual diff is authored from the real fixture.', diff);
const check = () => item('Independent verifier', 'test-rig', 'The downloaded Node script checks complete expected files. A successful edit tool alone does not satisfy it.', verifier);

