/** A different provider topology, inspectable code, and five causal frames for each topic. */
export function providerStage(provider: PublicProvider, topic: StageTopic): StageSpec {
  const meta = providerMeta[provider], story = stories[provider][topic];
  const nodes: StageNode[] = story.nodes.map(([label, asset, detail, snippet], index) => ({ id: `p${index}`, label, asset, detail, code: { ...snippet, highlight: [...(snippet.highlight || [1])] }, position: [meta.positions[index][0], 0, meta.positions[index][1]] }));
  if (topic === 'permissions') {
    nodes[4] = { ...nodes[4], label: 'Unchanged task document', asset: 'editor', detail: 'The denied proposal did not execute. The typo remains; containment did not complete the user task.', code: { ...original, highlight: [1, 3] } };
    nodes[5] = { ...nodes[5], label: 'Containment evidence · task pending', detail: 'This is the authored denied state, not a passing verifier or a claim that a live operation was blocked.', code: pseudo('denied-frame.txt · teaching state', 'Outside-scope proposal: denied before execution\nOutside-scope effect: none in this teaching state\nhelp.md: original typo remains\nTask acceptance: not satisfied\nNext work: propose the authorized correction, then verify it', meta.sources[0].url, [1, 2, 3, 4]) };
  }
  const linkLabels = topic === 'recovery' ? ['restore context', 'recover observation', 'reconcile identity', 'inspect current effect', 'revalidate'] : topic === 'permissions' ? ['scope', 'propose', 'check before dispatch', 'permitted effect only', 'verify outcome'] : ['task context', 'load / propose', 'runtime seam', 'bounded operation', 'acceptance evidence'];
  const focusIndices = [0, 1, 2, 3, 5];
  return {
    id: `${provider}-${topic}`, title: story.title,
    subtitle: `${meta.name} · ${topic} · inspect the real configuration seam and the teaching artifact`,
    provider: meta.name, layout: meta.layout, nodes,
    links: nodes.slice(1).map((node, index) => ({ from: `p${index}`, to: node.id, label: linkLabels[index], kind: topic === 'recovery' && index < 3 ? 'checkpoint' : index === 0 ? 'context' : index === 1 ? 'proposal' : index === 4 ? 'result' : 'action' })),
    frames: story.beats.map(([title, explanation], index) => {
      const at = focusIndices[index], blocked = story.blocked === at;
      const deniedEvidence = topic === 'permissions' && index === 4;
      const focus = index === 4 ? ['p5', 'p4'] : [`p${at}`];
      return { id: `${provider}-${topic}-${index + 1}`, title: deniedEvidence ? 'Inspect containment; the task is still pending' : title, explanation: deniedEvidence ? `${meta.name} has not executed the denied proposal in this teaching state. The original typo remains. Containment is evidence about the boundary, not a passing artifact check; a new authorized correction and verification are still required.` : explanation, focus,
        route: Array.from({ length: (deniedEvidence ? story.blocked! : at) + 1 }, (_, i) => `p${i}`),
        code: { ...nodes[at].code, highlight: [...(nodes[at].code.highlight || [1])] },
        states: Object.fromEntries(nodes.map((node, i) => [node.id, deniedEvidence ? i === story.blocked ? 'blocked' : i === at ? 'active' : i < story.blocked! ? 'passed' : 'ready' : i === at ? blocked ? 'blocked' : index === 4 ? 'passed' : 'active' : i < at ? 'passed' : 'ready'])),
        packet: blocked ? 'Proposal stopped before effect' : deniedEvidence ? 'Containment observed · task pending' : index === 4 ? 'Inspect acceptance evidence' : topic === 'recovery' ? 'Restore and revalidate' : 'Follow this handoff',
      };
    }),
    sources: meta.sources.map(source => ({ ...source })),
    note: 'Authored educational cutaway; no provider is executed. Workshop file excerpts are real. API examples use documented fields but are not installed; wire payloads and pseudocode are labeled. Hook scripts named in configuration must be implemented and reviewed separately. A session ID or tool-call ID does not provide business-operation idempotency. Sources reviewed 7 September 2026.',
  };
}
